IDS = ["u_green", "inverted_u_brown", "hex_blue", "hex_red", "base2", "base1"]

def check(ctx):
    tol = ctx.value("disturbance_tolerance_m")
    if "ref" not in ctx.state:
        ref = {}
        for oid in IDS:
            p = ctx.object_pose(oid)
            if p is not None:
                ref[oid] = p["pose"]["position"]
        ctx.state["ref"] = ref
        return None
    ref = ctx.state["ref"]
    for oid in IDS:
        p = ctx.object_pose(oid)
        if p is None:
            continue
        if oid not in ref:
            ref[oid] = p["pose"]["position"]
            continue
        d = ctx.dist(p["pose"]["position"], ref[oid])
        if d > tol:
            return {"value": d, "detail": oid + " displaced " + str(round(d, 4)) + " m from its rest pose"}
    return None

def check(ctx):
    j = ctx.joint("finger_joint")
    if j is None:
        return None
    e = abs(j["effort"])
    if "armed" not in ctx.state:
        ctx.state["armed"] = True
        ctx.state["effort_at_arm"] = e
        return None
    if e > ctx.value("max_clamp_effort"):
        return {"value": e, "detail": "finger_joint effort " + str(round(e, 3)) + " exceeds max_clamp_effort"}
    return None

