PART = "u_brown"

def rel(ctx):
    t = ctx.frame_pose("tcp")
    p = ctx.object_pose(PART)
    if t is None or p is None:
        return None
    return ctx.dist(t["pose"]["position"], p["pose"]["position"])

def check(ctx):
    if ctx.held_object() != PART:
        return None
    r = rel(ctx)
    if r is None:
        return None
