        ctx.state["ref"] = r
        return None
    drift = abs(r - ctx.state["ref"])
    if drift > ctx.value("grasp_slip_tolerance_m"):
        return {"value": drift, "detail": PART + " tcp distance changed by " + str(round(drift, 4)) + " m while held"}
    return None

